14	)
15	
16	// Block is one validated, deduplicated input block. Swaps are kept in
17	// canonical order: exact duplicates removed, sorted by Index.
18	type Block struct {
19		ChainID     string
20		BlockHash   string
21		BlockNumber int64
22		Swaps       []Swap
23	}
24	
25	// ReportFinding is one risk conclusion inside a block report. Evidence
26	// carries the raw fields of every swap that participated in the judgment.
27	type ReportFinding struct {
28		Kind     string `json:"kind"`
29		Severity int    `json:"severity"`
30		TxHash   string `json:"txHash"`
31		Evidence []Swap `json:"evidence"`
32	}
33	
34	// Report is the archived per-block risk report. Version records the full
35	// rule parameters that produced the findings, so the report stays
36	// interpretable without the original rule definition.
37	type Report struct {
38		ChainID     string          `json:"chainId"`
39		BlockHash   string          `json:"blockHash"`
40		BlockNumber int64           `json:"blockNumber"`
41		SwapCount   int             `json:"swapCount"`
42		Version     RuleVersion     `json:"version"`
43		Findings    []ReportFinding `json:"findings"`
44	}
45	
46	// LineError pins a replay failure to a 1-based input line.
47	type LineError struct {
48		Line int
49		Err  error
50	}
51	
52	func (e *LineError) Error() string { return fmt.Sprintf("line %d: %v", e.Line, e.Err) }
53	func (e *LineError) Unwrap() error { return e.Err }
54	
55	// ErrBusy reports an archive locked by another process.
56	var ErrBusy = errors.New("archive is busy")
57	
58	// ErrUnknownBlock reports a query for a block that was never archived.
59	var ErrUnknownBlock = errors.New("unknown block")
60	
61	type blockID struct {
62		chainID   string
63		blockHash string
64	}
65	
66	// swapLine mirrors one swap record inside a block line. Pointers
67	// distinguish a missing field (or an explicit null) from an explicit
68	// zero value: a replay record must be complete on its own, so In, Out,
69	// GasPrice and Index are all required and may not be null.
70	type swapLine struct {
71		TxHash   *string `json:"TxHash"`
72		Pool     *string `json:"Pool"`
73		Trader   *string `json:"Trader"`
74		In       *int64  `json:"In"`
75		Out      *int64  `json:"Out"`
76		GasPrice *int64  `json:"GasPrice"`
77		Index    *int    `json:"Index"`
78	}
79	
80	// blockLine mirrors one input line. Pointers distinguish a missing field
81	// from an explicit zero value.
82	type blockLine struct {
83		ChainID     *string     `json:"chainId"`
84		BlockHash   *string     `json:"blockHash"`
85		BlockNumber *int64      `json:"blockNumber"`
86		Swaps       *[]swapLine `json:"swaps"`
87	}
88	
89	func parseBlock(text string) (Block, error) {
90		var raw blockLine
91		dec := json.NewDecoder(strings.NewReader(text))
92		if err := dec.Decode(&raw); err != nil {
93			return Block{}, fmt.Errorf("invalid JSON: %w", err)
94		}
95		if err := blockTrailingData(text, int(dec.InputOffset())); err != nil {
96			return Block{}, err
97		}
98		if raw.ChainID == nil || *raw.ChainID == "" {
99			return Block{}, errors.New("chainId must be a non-empty string")
100		}
101		if raw.BlockHash == nil || *raw.BlockHash == "" {
102			return Block{}, errors.New("blockHash must be a non-empty string")
103		}
104		if raw.BlockNumber == nil {
105			return Block{}, errors.New("blockNumber is required")
106		}
107		if *raw.BlockNumber < 0 {
108			return Block{}, fmt.Errorf("blockNumber must be non-negative, got %d", *raw.BlockNumber)
109		}
110		if raw.Swaps == nil {
111			return Block{}, errors.New("swaps must be an array")
112		}
113	
114		byTx := make(map[string]Swap)
115		byIndex := make(map[int]string)
116		swaps := []Swap{}
117		for i, s := range *raw.Swaps {
118			if s.TxHash == nil || *s.TxHash == "" {
119				return Block{}, fmt.Errorf("swaps[%d]: TxHash must not be empty", i)
120			}
121			if s.Pool == nil || *s.Pool == "" {
122				return Block{}, fmt.Errorf("swaps[%d]: Pool must not be empty", i)
123			}
124			if s.Trader == nil || *s.Trader == "" {
125				return Block{}, fmt.Errorf("swaps[%d]: Trader must not be empty", i)
126			}
127			// Every numeric field must be present and non-null in this very
128			// record; an explicit zero is a valid value, never a missing one.
129			// Values must not be borrowed from a neighbour, a same-hash record
130			// or a default, so an incomplete record is rejected before dedup
131			// even when a complete record with the same tx hash exists.
132			for _, f := range []struct {
133				name string
134				v    *int64
135			}{
136				{"In", s.In}, {"Out", s.Out}, {"GasPrice", s.GasPrice},
137			} {
138				if f.v == nil {
139					return Block{}, fmt.Errorf("swaps[%d]: %s is required and must not be null", i, f.name)
140				}
141			}
142			if s.Index == nil {
143				return Block{}, fmt.Errorf("swaps[%d]: Index is required and must not be null", i)
144			}
145			in, out, gasPrice, index := *s.In, *s.Out, *s.GasPrice, *s.Index
146			if in < 0 || out < 0 || gasPrice < 0 || index < 0 {
147				return Block{}, fmt.Errorf("swaps[%d]: In, Out, GasPrice and Index must be non-negative", i)
148			}
149			swap := Swap{
150				TxHash: *s.TxHash, Pool: *s.Pool, Trader: *s.Trader,
151				In: in, Out: out, GasPrice: gasPrice, Index: index,
152			}
153			if prev, ok := byTx[swap.TxHash]; ok {
154				if prev != swap {
155					return Block{}, fmt.Errorf("swaps[%d]: conflicting records for tx %s", i, swap.TxHash)
156				}
157				continue // exact duplicate, keep one copy
158			}
159			if other, ok := byIndex[swap.Index]; ok {
160				return Block{}, fmt.Errorf("swaps[%d]: Index %d already used by tx %s", i, swap.Index, other)
161			}
162			byTx[swap.TxHash] = swap
163			byIndex[swap.Index] = swap.TxHash
164			swaps = append(swaps, swap)
165		}
166		sort.Slice(swaps, func(i, j int) bool { return swaps[i].Index < swaps[j].Index })
167		return Block{
168			ChainID:     *raw.ChainID,
169			BlockHash:   *raw.BlockHash,
170			BlockNumber: *raw.BlockNumber,
171			Swaps:       swaps,
172		}, nil
173	}
174	
175	// blockTrailingData names the first non-whitespace byte after the block
176	// object on a replay line, so an unmatched '}' or ']' — or a second value
177	// of any kind — is reported directly; only whitespace may follow the
178	// object. dec.More cannot see this: after a complete top-level value it
179	// only looks for the start of another value and treats stray closing
180	// brackets as "nothing more".
181	func blockTrailingData(text string, offset int) error {
182		rest := strings.TrimLeft(text[offset:], " \t\n\r")
183		if len(rest) > 0 {
184			return fmt.Errorf("invalid JSON: unexpected trailing data after block object: %s", trailingTokenName(rest[0]))
185		}
186		return nil
187	}
188	
189	func swapsEqual(a, b []Swap) bool {
190		if len(a) != len(b) {
191			return false
192		}
193		for i := range a {
194			if a[i] != b[i] {
195				return false
196			}
197		}
198		return true
199	}
200	
201	// sameContent reports whether two blocks carry the same content. Both sides
202	// are canonical (deduplicated, sorted by Index), so ordering and exact
203	// duplicates in the input do not affect the comparison.
204	func sameContent(blockNumber int64, swaps []Swap, b Block) bool {
205		return blockNumber == b.BlockNumber && swapsEqual(swaps, b.Swaps)
206	}
207	
208	// DetectBlock checks every swap against its adjacent neighbours within its
209	// pool under the built-in rules. See DetectBlockWithRules.
210	func DetectBlock(swaps []Swap) []ReportFinding {
211		return DetectBlockWithRules(swaps, BuiltinVersion().Rules)
212	}
213	
214	// DetectBlockWithRules checks every swap against its adjacent neighbours
215	// within its pool under the given rule version: a sandwich when the same
216	// trader brackets the victim with higher gas on both sides, otherwise a
217	// displacement when the previous swap's gas strictly exceeds the configured
218	// multiple of the victim's. The last swap of a pool is checked too. An
219	// enabled sandwich takes priority over displacement for the same victim;
220	// with the sandwich rule off the victim can still be flagged for
221	// displacement. With both rules off the result is an empty slice. The
222	// judgment itself is shared with Detect; this entry only adds the block
223	// report's raw-swap evidence and ordering.
224	func DetectBlockWithRules(swaps []Swap, rules RuleSet) []ReportFinding {
225		pools := make(map[string][]Swap)
226		for _, s := range swaps {
227			pools[s.Pool] = append(pools[s.Pool], s)
228		}
229		findings := []ReportFinding{}
230		for _, pool := range pools {
231			sort.Slice(pool, func(i, j int) bool { return pool[i].Index < pool[j].Index })
232			for i, victim := range pool {
233				var front, back *Swap
234				if i > 0 {
235					front = &pool[i-1]
236				}
237				if i+1 < len(pool) {
238					back = &pool[i+1]
239				}
240				j, hit := judgeVictim(front, victim, back, rules)
241				if !hit {
242					continue
243				}
244				// The evidence keeps the full swap fields of every record that
245				// participated: front, victim, and for a sandwich also back.
246				evidence := []Swap{*front, victim}
247				if j.kind == "sandwich" {
248					evidence = append(evidence, *back)
249				}
250				findings = append(findings, ReportFinding{
251					Kind: j.kind, Severity: j.severity, TxHash: victim.TxHash,
252					Evidence: evidence,
253				})
254			}
255		}
256		sort.Slice(findings, func(i, j int) bool {
257			if findings[i].Severity != findings[j].Severity {
258				return findings[i].Severity > findings[j].Severity
259			}
260			return findings[i].TxHash < findings[j].TxHash
261		})
262		return findings
263	}
264	
265	// record is the archived form of a block: the report plus the canonical
266	// swaps, so a later import can detect content conflicts. Version carries
267	// the full rule parameters used for the findings; it is nil only in
268	// archives written before rule versions existed, which are interpreted
269	// under the built-in rules.
270	type record struct {
271		ChainID     string          `json:"chainId"`
272		BlockHash   string          `json:"blockHash"`
273		BlockNumber int64           `json:"blockNumber"`
274		Swaps       []Swap          `json:"swaps"`
275		Findings    []ReportFinding `json:"findings"`
276		Version     *RuleVersion    `json:"version,omitempty"`
277	}
278	
279	func (r record) id() blockID { return blockID{r.ChainID, r.BlockHash} }
280	
281	func (r record) ruleVersion() RuleVersion {
282		if r.Version != nil {
283			return *r.Version
284		}
285		return BuiltinVersion()
286	}
287	
288	// queryRecord mirrors one archived record the way a report query reads it.
289	// Every business field is decoded normally, but the archived rule-version
290	// declaration is kept as its raw stored document. The decoded struct cannot
291	// tell a missing field, an explicit null or a wrong-typed value from a real
292	// one: decoding the embedded version into the struct would show a decayed
293	// report under silently zeroed parameters (enabled false, severity 0, a
294	// zero displacement multiplier), and — because a null or incomplete
295	// declaration carries no usable id — risk explaining it as the built-in
296	// rules. A zero-length Version means the "version" key is absent entirely
297	// (a value-type RawMessage is left untouched for a missing key), which
298	// alone is the legacy, pre-version format interpreted under the built-in
299	// rules; any present value — the bytes "null", {} or an object — is kept
300	// byte for byte and must be re-validated from those bytes before the
301	// report is shown.
302	type queryRecord struct {
303		ChainID     string          `json:"chainId"`
304		BlockHash   string          `json:"blockHash"`
305		BlockNumber int64           `json:"blockNumber"`
306		Swaps       []Swap          `json:"swaps"`
307		Findings    []ReportFinding `json:"findings"`
308		Version     json.RawMessage `json:"version"`
309	}
310	
311	// archivedReportVersion proves the version declaration embedded in an
312	// archived record still satisfies every registration rule, re-validating
313	// the raw document with the same parser registrations pass. A wholly
314	// absent "version" key is the only legacy shape and means the built-in
315	// rules; anything actually saved — null, an empty object, an incomplete
316	// declaration, a wrong type, an out-of-range number, an unknown or
317	// duplicated field — is corruption rather than a zero-filled or built-in
318	// parameter set. An id of "builtin" names the same saved declaration and
319	// is validated just like any other id; it never bypasses the check.
320	func archivedReportVersion(raw json.RawMessage) (RuleVersion, error) {
321		if len(raw) == 0 {
322			return BuiltinVersion(), nil
323		}
324		return ParseRuleVersion(raw)
325	}
326	
327	// corruptReportError names the chain and block a failed report query
328	// targets, the saved version identifier when the document still carries a
329	// readable one (so corruption is not mistaken for an unregistered
330	// version), and the offending rule or field from the validation failure.
331	// It wraps both ErrCorruptVersion and the underlying cause (for example
332	// ErrDuplicateField).
333	func corruptReportError(chainID, blockHash string, raw json.RawMessage, cause error) error {
334		if id := identifiableVersionID(raw); id != "unidentifiable version" {
335			return fmt.Errorf("%w: archived report for chain %s block %s uses version %q: %w",
336				ErrCorruptVersion, chainID, blockHash, id, cause)
337		}
338		return fmt.Errorf("%w: archived report for chain %s block %s: %w",
339			ErrCorruptVersion, chainID, blockHash, cause)
340	}
341	
342	func (r record) report() Report {
343		return Report{
344			ChainID:     r.ChainID,
345			BlockHash:   r.BlockHash,
346			BlockNumber: r.BlockNumber,
347			SwapCount:   len(r.Swaps),
348			Version:     r.ruleVersion(),
349			Findings:    r.Findings,
350		}
351	}
352	
353	const (
354		archiveFileName = "archive.json"
355		lockFileName    = "lock"
356	)
357	
358	type archiveData struct {
359		Records []record `json:"records"`
360		// Versions and EnabledVersion are absent in archives written before
361		// rule versions existed; such archives run the built-in rules.
362		Versions       []RuleVersion `json:"versions,omitempty"`
363		EnabledVersion string        `json:"enabledVersion,omitempty"`
364		// Suppressions and AlertRecords are absent in archives written before
365		// offline alerting existed; such archives simply have no registered
366		// conditions and no processing history.
367		Suppressions []Suppression      `json:"suppressions,omitempty"`
368		AlertRecords []ProcessingRecord `json:"alerts,omitempty"`
369		// Reviews is absent in archives written before manual reviews existed;
370		// every conclusion then behaves as unreviewed.
371		Reviews []ReviewObject `json:"reviews,omitempty"`
372	}
373	
374	// readArchiveBytes returns the exact bytes of the archive file, or nil
375	// when no archive exists yet.
376	func readArchiveBytes(dir string) ([]byte, error) {
377		raw, err := os.ReadFile(filepath.Join(dir, archiveFileName))
378		if errors.Is(err, os.ErrNotExist) {
379			return nil, nil
380		}
381		if err != nil {
382			return nil, err
383		}
384		return raw, nil
385	}
386	
387	func readArchive(dir string) (archiveData, error) {
388		raw, err := readArchiveBytes(dir)
389		if err != nil {
390			return archiveData{}, err
391		}
392		if raw == nil {
393			return archiveData{Records: []record{}}, nil
394		}
395		var data archiveData
396		if err := json.Unmarshal(raw, &data); err != nil {
397			return archiveData{}, fmt.Errorf("archive is corrupted: %w", err)
398		}
399		return data, nil
400	}
401	
402	// replayArchiveDoc mirrors the archive file the way a replay reads and
403	// writes it: records, suppressions, alert records and reviews are fully
404	// decoded, but each registered version is kept as its raw stored document.
405	// A corrupt version entry — a wrong-typed field, say — then cannot break
406	// the read or masquerade as whole-archive corruption; the version this run
407	// selects is judged on its own by intactVersion, and entries the run does
408	// not select are written back byte for byte: a replay never repairs,
409	// completes or drops a stored version, not even a corrupt one.
410	type replayArchiveDoc struct {
411		Records        []record           `json:"records"`
412		Versions       []json.RawMessage  `json:"versions,omitempty"`
413		EnabledVersion string             `json:"enabledVersion,omitempty"`
414		Suppressions   []Suppression      `json:"suppressions,omitempty"`
415		AlertRecords   []ProcessingRecord `json:"alerts,omitempty"`
416		Reviews        []ReviewObject     `json:"reviews,omitempty"`
417	}
418	
419	// writeArchiveAtomic replaces the archive file in one rename, so a crash
420	// can only expose the previous or the next complete commit, never a half
421	// written file.
422	func writeArchiveAtomic(dir string, data any) error {
423		raw, err := json.MarshalIndent(data, "", "  ")
424		if err != nil {
425			return err
426		}
427		tmp := filepath.Join(dir, archiveFileName+".tmp")
428		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
429		if err != nil {
430			return err
431		}
432		if _, err := f.Write(raw); err != nil {
433			f.Close()
434			os.Remove(tmp)
435			return err
436		}
437		if err := f.Sync(); err != nil {
438			f.Close()
439			os.Remove(tmp)
440			return err
441		}
442		if err := f.Close(); err != nil {
443			os.Remove(tmp)
444			return err
445		}
446		if err := os.Rename(tmp, filepath.Join(dir, archiveFileName)); err != nil {
447			os.Remove(tmp)
448			return err
449		}
450		if d, err := os.Open(dir); err == nil {
451			d.Sync()
452			d.Close()
453		}
454		return nil
455	}
456	
457	// lockArchive takes an flock on the archive's lock file. The lock is
458	// released automatically if the process dies, so no stale locks survive.
459	func lockArchive(dir string, how int) (*os.File, error) {
460		f, err := os.OpenFile(filepath.Join(dir, lockFileName), os.O_CREATE|os.O_RDWR, 0o644)
461		if err != nil {
462			return nil, err
463		}
464		if err := syscall.Flock(int(f.Fd()), how); err != nil {
465			f.Close()
466			if errors.Is(err, syscall.EWOULDBLOCK) {
467				return nil, ErrBusy
468			}
469			return nil, err
470		}
471		return f, nil
472	}
473	
474	type parsedBlock struct {
475		line  int
476		block Block
477	}
478	
479	func parseBlocks(r io.Reader) ([]parsedBlock, error) {
480		var out []parsedBlock
481		reader := bufio.NewReader(r)
482		lineNo := 0
483		for {
484			raw, err := reader.ReadBytes('\n')
485			if len(raw) > 0 {
486				lineNo++
487			}
488			if text := strings.TrimSpace(string(raw)); text != "" {
489				block, perr := parseBlock(text)
490				if perr != nil {
491					return nil, &LineError{Line: lineNo, Err: perr}
492				}
493				out = append(out, parsedBlock{line: lineNo, block: block})
494			}
495			if err == io.EOF {
496				return out, nil
497			}
498			if err != nil {
499				return nil, err
500			}
501		}
502	}
503	
504	// ReplayFile imports the line-delimited blocks in inputPath into the
505	// archive at dir and returns one report per distinct block, in order of
506	// first appearance. New blocks are judged under the archive's currently
507	// enabled rule version; that version's stored document must still satisfy
508	// the registration rules in full, or the whole replay fails with
509	// ErrCorruptVersion before any report is produced.
510	func ReplayFile(inputPath, dir string) ([]Report, error) {
511		return replayFile(inputPath, dir, "")
512	}
513	
514	// ReplayFileWithVersion is ReplayFile under an explicitly registered rule
515	// version instead of the archive's enabled one. The named version's stored
516	// document must still satisfy the registration rules in full; a corrupt
517	// one fails the whole replay with ErrCorruptVersion rather than judging
518	// under zeroed or substituted parameters.
519	func ReplayFileWithVersion(inputPath, dir, versionID string) ([]Report, error) {
520		if versionID == "" {
521			return nil, errors.New("version id must not be empty")
522		}
523		return replayFile(inputPath, dir, versionID)
524	}
525	
526	func replayFile(inputPath, dir, versionID string) ([]Report, error) {
527		f, err := os.Open(inputPath)
528		if err != nil {
529			return nil, err
530		}
531		defer f.Close()
532		return doReplay(f, dir, versionID)
533	}
534	
535	// Replay parses, validates and archives blocks from r under the archive's
536	// currently enabled rule version. Every line is checked before anything is
537	// written; any failure leaves the archive untouched. New reports are
538	// committed together in a single atomic write. The selected version's
539	// stored document is re-validated before any block is judged: a corrupt
540	// version fails the whole replay with ErrCorruptVersion — never a
541	// substituted or zeroed parameter set — even when no input block would
542	// have triggered the damaged rule.
543	func Replay(input io.Reader, dir string) ([]Report, error) {
544		return doReplay(input, dir, "")
545	}
546	
547	// ReplayWithVersion is Replay under an explicitly registered rule version
548	// instead of the archive's enabled one, with the same integrity check: a
549	// corrupt stored version document fails the whole replay with
550	// ErrCorruptVersion before any report is produced.
551	func ReplayWithVersion(input io.Reader, dir, versionID string) ([]Report, error) {
552		if versionID == "" {
553			return nil, errors.New("version id must not be empty")
554		}
555		return doReplay(input, dir, versionID)
556	}
557	
558	func doReplay(input io.Reader, dir, versionID string) ([]Report, error) {
559		parsed, err := parseBlocks(input)
560		if err != nil {
561			return nil, err
562		}
563	
564		// Collapse repeated identities within this file, keeping first
565		// appearance order; conflicting content rejects the whole file.
566		type occurrence struct {
567			block Block
568			line  int
569		}
570		order := []occurrence{}
571		firstSeen := make(map[blockID]int)
572		for _, p := range parsed {
573			id := blockID{p.block.ChainID, p.block.BlockHash}
574			if first, ok := firstSeen[id]; ok {
575				if !sameContent(order[first].block.BlockNumber, order[first].block.Swaps, p.block) {
576					return nil, &LineError{Line: p.line, Err: fmt.Errorf(
577						"block %s/%s conflicts with line %d", id.chainID, id.blockHash, order[first].line)}
578				}
579				continue
580			}
581			firstSeen[id] = len(order)
582			order = append(order, occurrence{block: p.block, line: p.line})
583		}
584	
585		if err := os.MkdirAll(dir, 0o755); err != nil {
586			return nil, err
587		}
588		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
589		if err != nil {
590			return nil, err
591		}
592		defer lock.Close()
593	
594		// Decode with each registered version kept as its raw stored document,
595		// so a wrong-typed field in one version is that version's corruption,
596		// not whole-archive corruption, and the selected version's document can
597		// be re-validated from its bytes the same way a single-block comparison
598		// proves its version intact.
599		raw, err := readArchiveBytes(dir)
600		if err != nil {
601			return nil, err
602		}
603		data := replayArchiveDoc{Records: []record{}}
604		if raw != nil {
605			if err := json.Unmarshal(raw, &data); err != nil {
606				return nil, fmt.Errorf("archive is corrupted: %w", err)
607			}
608		}
609		// Resolve the version once, while the exclusive lock is held: every
610		// new block in this run is judged under the same rules even if another
611		// process enables a different version right after we finish. The
612		// selected version's stored document must still satisfy the
613		// registration rules in full; a corrupt one fails the whole replay
614		// with ErrCorruptVersion here, before any block is judged, any report
615		// is produced or anything is written — even when the input is empty,
616		// holds only blocks already archived, or would never trigger the
617		// damaged rule. The corrupt content is never replaced by the enabled
618		// version, the built-in rules or defaults.
619		version, err := resolveReplayVersion(data, versionID)
620		if err != nil {
621			return nil, err
622		}
623		archived := make(map[blockID]int, len(data.Records))
624		for i, rec := range data.Records {
625			archived[rec.id()] = i
626		}
627	
628		reports := make([]Report, 0, len(order))
629		changed := false
630		for _, occ := range order {
631			id := blockID{occ.block.ChainID, occ.block.BlockHash}
632			if idx, ok := archived[id]; ok {
633				rec := data.Records[idx]
634				if !sameContent(rec.BlockNumber, rec.Swaps, occ.block) {
635					return nil, &LineError{Line: occ.line, Err: fmt.Errorf(
636						"block %s/%s conflicts with the archived record", id.chainID, id.blockHash)}
637				}
638				// Identical re-import: return the original report, add nothing.
639				reports = append(reports, rec.report())
640				continue
641			}
642			rec := record{
643				ChainID:     occ.block.ChainID,
644				BlockHash:   occ.block.BlockHash,
645				BlockNumber: occ.block.BlockNumber,
646				Swaps:       occ.block.Swaps,
647				Findings:    DetectBlockWithRules(occ.block.Swaps, version.Rules),
648				Version:     &version,
649			}
650			archived[id] = len(data.Records)
651			data.Records = append(data.Records, rec)
652			reports = append(reports, rec.report())
653			changed = true
654		}
655		if changed {
656			if err := writeArchiveAtomic(dir, data); err != nil {
657				return nil, err
658			}
659		}
660		return reports, nil
661	}
662	
663	// resolveReplayVersion picks the rule version for one replay run — the
664	// explicitly requested one, or the archive's currently enabled version —
665	// and proves its stored archive document still satisfies every
666	// registration rule, re-validating the raw document with the same parser
667	// registrations pass. The decoded struct cannot do this: a missing
668	// enabled, severity or multiplier field unmarshals as the zero value and
669	// is indistinguishable from an explicitly declared one, and a zero
670	// displacement multiplier even crashes detection. An explicitly declared
671	// false or any in-range value is valid; a missing or null field, a wrong
672	// type or an out-of-range number makes the version corrupt, and the
673	// failure names the version and the offending rule or field. Archives
674	// written before rule versions existed have no enabled marker and run the
675	// built-in rules; the built-in version is constructed in code and always
676	// intact.
677	func resolveReplayVersion(data replayArchiveDoc, versionID string) (RuleVersion, error) {
678		id := versionID
679		if id == "" {
680			id = data.EnabledVersion
681			if id == "" {
682				return BuiltinVersion(), nil
683			}
684		}
685		return intactVersion(data.Versions, id)
686	}
687	
688	// queryArchiveDoc mirrors just the records a report query reads, keeping
689	// each record's embedded version declaration as its raw stored document —
690	// the same shape registered versions are kept in everywhere else — so a
691	// wrong-typed field in one report's declaration fails that report's query
692	// rather than breaking the whole-archive decode or decoding into silently
693	// zeroed parameters.
694	type queryArchiveDoc struct {
695		Records []queryRecord `json:"records"`
696	}
697	
698	// Query returns the archived report for one block identity. It only reads
699	// the archive; the original input file is not needed, and neither a
700	// successful nor a failed query rewrites anything.
701	//
702	// Before the report is returned, the complete version declaration the
703	// report archived is re-validated from its raw bytes with the same proof
704	// registration, enable, comparison, evaluation and replay demand: a
705	// non-empty version identifier, both the sandwich and displacement rules
706	// each with a boolean enabled and an integer severity in 1-5, and the
707	// displacement multiplier an integer in 2-100. A missing or null field or
708	// rule object, a wrong type, an out-of-range number, an unknown field or
709	// rule, or a field declared twice in one object (an exact repeat, an
710	// escaped spelling or a case-only spelling that names the same field —
711	// even when both values agree) makes the saved declaration corrupt. An
712	// explicit enabled:false is a legal off state, not damage; the disabled
713	// rule still has to carry complete, in-range parameters.
714	//
715	// Only an old-format record with no "version" key at all keeps the
716	// original built-in interpretation. A declaration actually saved as null,
717	// as an empty object or only in part is corruption, and an id of
718	// "builtin" is validated like every other id rather than bypassing the
719	// check. On corruption Query fails with ErrCorruptVersion naming the
720	// target chain and block, the readable saved version id and the offending
721	// rule or field; it never zero-fills the parameters, explains them as
722	// built-in, or substitutes parameters from the currently enabled or a
723	// registered version. The report uses the parameters it archived and is
724	// never re-detected. A block that was never archived stays
725	// ErrUnknownBlock.
726	func Query(dir, chainID, blockHash string) (Report, error) {
727		if _, err := os.Stat(dir); err != nil {
728			if errors.Is(err, os.ErrNotExist) {
729				return Report{}, ErrUnknownBlock
730			}
731			return Report{}, err
732		}
733		lock, err := lockArchive(dir, syscall.LOCK_SH)
734		if err != nil {
735			return Report{}, err
736		}
737		defer lock.Close()
738	
739		raw, err := readArchiveBytes(dir)
740		if err != nil {
741			return Report{}, err
742		}
743		var doc queryArchiveDoc
744		if len(raw) > 0 {
745			if err := json.Unmarshal(raw, &doc); err != nil {
746				return Report{}, fmt.Errorf("archive is corrupted: %w", err)
747			}
748		}
749		idx := -1
750		for i := range doc.Records {
751			if doc.Records[i].ChainID == chainID && doc.Records[i].BlockHash == blockHash {
752				idx = i
753				break
754			}
755		}
756		if idx < 0 {
757			return Report{}, ErrUnknownBlock
758		}
759		rec := &doc.Records[idx]
760	
761		// Prove the saved declaration before presenting the report. A wholly
762		// absent version key is the only legacy shape and means builtin; every
763		// declaration that was actually written must stand on its own.
764		version, err := archivedReportVersion(rec.Version)
765		if err != nil {
766			return Report{}, corruptReportError(chainID, blockHash, rec.Version, err)
767		}
768	
769		findings := rec.Findings
770		return Report{
771			ChainID:     rec.ChainID,
772			BlockHash:   rec.BlockHash,
773			BlockNumber: rec.BlockNumber,
774			SwapCount:   len(rec.Swaps),
775			Version:     version,
776			Findings:    findings,
777		}, nil
778	}
779

